import"./strings.m.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{getRequiredElement}from"chrome://resources/js/util_ts.js";import{Url}from"chrome://resources/mojo/url/mojom/url.mojom-webui.js";import{WebAppInternalsHandler}from"./web_app_internals.mojom-webui.js";const webAppInternalsHandler=WebAppInternalsHandler.getRemote();const debugInfoAsJsonString=webAppInternalsHandler.getDebugInfoAsJsonString().then((response=>response.result));const iwaInstallButton=getRequiredElement("iwa-install-button");const iwaInstallUrl=getRequiredElement("iwa-install-url");const iwaSelectFileButton=getRequiredElement("iwa-select-bundle");const iwaSearchForUpdatesButton=getRequiredElement("iwa-search-for-updates");function originToText(origin){if(origin.host.length===0){return"null"}let result=origin.scheme+"://"+origin.host;if(!(origin.scheme==="https"&&origin.port===443)&&!(origin.scheme==="http"&&origin.port===80)){result+=":"+origin.port}return result}getRequiredElement("copy-button").addEventListener("click",(async()=>{navigator.clipboard.writeText(await debugInfoAsJsonString)}));getRequiredElement("download-button").addEventListener("click",(async()=>{const url=URL.createObjectURL(new Blob([await debugInfoAsJsonString],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download="web_app_internals.json";a.click();URL.revokeObjectURL(url)}));function iwaInstallStateUpdate(){iwaInstallButton.disabled=iwaInstallUrl.value.length===0}async function iwaInstallSubmit(){iwaInstallButton.disabled=true;const iwaInstallMessageDiv=getRequiredElement("iwa-install-message-div");let valid=false;try{new URL(iwaInstallUrl.value);valid=iwaInstallUrl.value.startsWith("http:")||iwaInstallUrl.value.startsWith("https:")}catch(_){}if(!valid){iwaInstallMessageDiv.innerText=`Installing IWA: ${iwaInstallUrl.value} is not a valid URL`;iwaInstallStateUpdate();return}iwaInstallMessageDiv.innerText=`Installing IWA: ${iwaInstallUrl.value}...`;const location=new Url;location.url=iwaInstallUrl.value;const installFromDevProxy=await webAppInternalsHandler.installIsolatedWebAppFromDevProxy(location);if(installFromDevProxy.result.success){iwaInstallMessageDiv.innerText=`Installing IWA: ${iwaInstallUrl.value} successfully installed.`;iwaInstallUrl.value="";iwaInstallStateUpdate();return}iwaInstallMessageDiv.innerText=`Installing IWA: ${iwaInstallUrl.value} failed to install: ${installFromDevProxy.result.error}`;iwaInstallStateUpdate()}iwaInstallUrl.addEventListener("enter",iwaInstallSubmit);iwaInstallButton.addEventListener("click",iwaInstallSubmit);function updateIwaInstallButtonState(event){if(event.key==="Enter"){event.preventDefault();iwaInstallSubmit();return}iwaInstallStateUpdate()}iwaInstallUrl.addEventListener("keyup",updateIwaInstallButtonState);iwaInstallStateUpdate();async function iwaSelectFile(){const iwaInstallMessageDiv=getRequiredElement("iwa-install-message-div");iwaInstallMessageDiv.innerText=`Installing IWA from bundle...`;const installFromDevBundle=await webAppInternalsHandler.selectFileAndInstallIsolatedWebAppFromDevBundle();if(installFromDevBundle.result.success){iwaInstallMessageDiv.innerText=`Installing IWA: successfully installed.`;return}iwaInstallMessageDiv.innerText=`Installing IWA: failed to install: ${installFromDevBundle.result.error}`}iwaSelectFileButton.addEventListener("click",iwaSelectFile);async function iwaSearchForUpdates(){const messageDiv=getRequiredElement("iwa-update-discovery-message-div");messageDiv.innerText=`Queueing update discovery tasks...`;const{result:result}=await webAppInternalsHandler.searchForIsolatedWebAppUpdates();messageDiv.innerText=result}iwaSearchForUpdatesButton.addEventListener("click",iwaSearchForUpdates);document.addEventListener("DOMContentLoaded",(async()=>{getRequiredElement("json").innerText=await debugInfoAsJsonString;if(loadTimeData.getBoolean("experimentalAreIwasEnabled")){getRequiredElement("iwa-div").style.display="";if(loadTimeData.getBoolean("experimentalIsIwaDevModeEnabled")){getRequiredElement("iwa-install-div").style.display="";const devModeProxyAppList=getRequiredElement("iwa-dev-mode-proxy-app-list");const{apps:devModeProxyApps}=await webAppInternalsHandler.getIsolatedWebAppDevModeProxyAppInfo();for(const devModeProxyApp of devModeProxyApps){const li=document.createElement("li");li.innerText=`${devModeProxyApp.name} (${devModeProxyApp.installedVersion}) -> ${originToText(devModeProxyApp.proxyOrigin)}`;const updateMsg=document.createElement("p");const updateBtn=document.createElement("button");updateBtn.className="iwa-update-btn";updateBtn.innerText="Perform update now";updateBtn.onclick=async()=>{const oldText=updateBtn.innerText;try{updateBtn.disabled=true;updateBtn.innerText="Performing update... (close the IWA if it is currently open!)";const{result:result}=await webAppInternalsHandler.updateDevProxyIsolatedWebApp(devModeProxyApp.appId);updateMsg.innerText=result}finally{updateBtn.innerText=oldText;updateBtn.disabled=false}};li.appendChild(updateBtn);li.appendChild(updateMsg);devModeProxyAppList.appendChild(li)}getRequiredElement("iwa-dev-mode-proxy-updates").style.display=""}}}));